class Solution {
public:
    vector<long long> mostFrequentIDs(vector<int>& nums, vector<int>& freq) {
        unordered_map<int, long long> counts;
        priority_queue<pair<long long, int>> pq;
        vector<long long> ans;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            counts[nums[i]] += freq[i];
            pq.push({counts[nums[i]], nums[i]});
            while (!pq.empty() && pq.top().first != counts[pq.top().second]) {
                pq.pop();
            }
            ans.push_back(pq.empty() ? 0 : pq.top().first);
        }
        return ans;
    }
};

class Solution {
    public long[] mostFrequentIDs(int[] nums, int[] freq) {
        Map<Integer, Long> counts = new HashMap<>();
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(b[0], a[0]));
        int n = nums.length;
        long[] ans = new long[n];
        for (int i = 0; i < n; i++) {
            long newF = counts.getOrDefault(nums[i], 0L) + freq[i];
            counts.put(nums[i], newF);
            pq.offer(new long[]{newF, nums[i]});
            while (!pq.isEmpty() && pq.peek()[0] != counts.getOrDefault((int) pq.peek()[1], 0L)) {
                pq.poll();
            }
            ans[i] = pq.isEmpty() ? 0 : pq.peek()[0];
        }
        return ans;
    }
}

var mostFrequentIDs = function(nums, freq) {
    const counts = new Map();
    // Using a binary max heap implementation
    const heap = [];
    function push(val) {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            let p = Math.floor((idx - 1) / 2);
            if (heap[p][0] < heap[idx][0]) {
                [heap[p], heap[idx]] = [heap[idx], heap[p]];
                idx = p;
            } else break;
        }
    }
    function pop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < heap.length && heap[left][0] > heap[best][0]) best = left;
                if (right < heap.length && heap[right][0] > heap[best][0]) best = right;
                if (best !== idx) {
                    [heap[best], heap[idx]] = [heap[idx], heap[best]];
                    idx = best;
                } else break;
            }
        }
        return top;
    }
    const ans = [];
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i], f = freq[i];
        const newF = (counts.get(x) || 0) + f;
        counts.set(x, newF);
        push([newF, x]);
        while (heap.length > 0 && heap[0][0] !== (counts.get(heap[0][1]) || 0)) {
            pop();
        }
        ans.push(heap.length > 0 ? heap[0][0] : 0);
    }
    return ans;
};
